const $=s=>document.querySelector(s), key='clareza.tasks.v1';
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
let tasks=[],view='today',priority='all',editing=null,undo=null,timer;
try{const data=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(data))tasks=data.filter(t=>t&&typeof t.id==='string'&&typeof t.title==='string').map(t=>({...t,date:typeof t.date==='string'?t.date:'',notes:typeof t.notes==='string'?t.notes:'',priority:t.priority==='high'?'high':'normal'}))}catch{notify('Não foi possível carregar as tarefas salvas. Exporte seus dados antes de limpar o navegador.')}
function notify(message,canUndo=false){clearTimeout(timer);$('#toast span').textContent=message;$('#toast button').hidden=!canUndo;$('#toast').hidden=false;timer=setTimeout(()=>$('#toast').hidden=true,canUndo?9000:5000)}
function save(){try{localStorage.setItem(key,JSON.stringify(tasks));return true}catch{notify('Não foi possível salvar no navegador. Exporte suas tarefas para preservar os dados.');return false}}
function formatDate(value){if(!value)return 'Sem prazo';const today=dateKey();if(value===today)return 'Hoje';return new Date(value+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'short'})}
const names={today:['Seu dia, com clareza.','Escolha o próximo passo. O resto pode esperar.','Seu foco de hoje','Hoje'],all:['Tudo no seu lugar.','Tire as tarefas da cabeça e organize seus próximos passos.','Todas as tarefas','Todas as tarefas'],upcoming:['Abra espaço para a semana.','Veja o que vem pela frente e prepare seu próximo passo.','Próximos dias','Próximos dias'],done:['Você deu esses passos.','Reconheça o que já fez e siga no seu ritmo.','Tarefas concluídas','Concluídas']};
function render(){const today=dateKey(),pending=tasks.filter(t=>!t.done),forToday=tasks.filter(t=>t.date===today),doneToday=tasks.filter(t=>t.done&&t.completedAt&&dateKey(new Date(t.completedAt))===today);$('#date-label').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});const n=names[view];$('#title').textContent=n[0];$('#subtitle').textContent=n[1];$('#list-title').textContent=n[2];$('#breadcrumb').textContent=n[3];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#stat-today').textContent=forToday.filter(t=>!t.done).length;$('#stat-done').textContent=doneToday.length;$('#stat-late').textContent=pending.filter(t=>t.date&&t.date<today).length;const pc=forToday.length?Math.round(forToday.filter(t=>t.done).length/forToday.length*100):0;$('#percent').textContent=pc+'%';$('#progress').value=pc;$('#progress-caption').textContent=forToday.length?`${forToday.filter(t=>t.done).length} de ${forToday.length} tarefas`:'Nenhuma tarefa para hoje';const query=$('#search').value.toLocaleLowerCase('pt-BR');let list=tasks.filter(t=>view==='done'?t.done:view==='today'?!t.done&&t.date&&t.date<=today:view==='upcoming'?!t.done&&t.date>today:!t.done).filter(t=>priority==='all'||t.priority===priority).filter(t=>(t.title+' '+t.notes).toLocaleLowerCase('pt-BR').includes(query));list.sort((a,b)=>$('#sort').value==='priority'?Number(b.priority==='high')-Number(a.priority==='high')||(a.date||'9999').localeCompare(b.date||'9999'):(a.date||'9999').localeCompare(b.date||'9999')||Number(b.priority==='high')-Number(a.priority==='high'));$('#count').textContent=list.length;$('#tasks').replaceChildren();if(!list.length){const empty=document.createElement('div');empty.className='empty';const filtered=query||priority!=='all';empty.innerHTML='<div class="symbol">'+(filtered?'⌕':'✓')+'</div><h3></h3><p></p><button class="primary">＋ Criar uma tarefa</button>';empty.querySelector('h3').textContent=filtered?'Nenhuma tarefa encontrada':view==='done'?'Suas conquistas aparecem aqui':view==='today'?'Seu dia começa com um passo':'Espaço para o que vem a seguir';empty.querySelector('p').textContent=filtered?'Ajuste a busca ou o filtro para ver outras tarefas.':view==='done'?'Ao concluir uma tarefa, você poderá encontrá-la aqui.':'Adicione uma tarefa e transforme uma intenção em ação.';empty.querySelector('button').hidden=filtered||view==='done';empty.querySelector('button').onclick=()=>openTask();$('#tasks').append(empty)}for(const t of list){const row=document.createElement('div');row.className='task'+(t.done?' done':'');row.innerHTML='<input type="checkbox"><div class="task-content"><button class="task-title"></button><div class="task-meta"><span class="deadline"></span><span class="badge"></span></div></div><button class="edit" aria-label="Editar tarefa">⋯</button>';const checkbox=row.querySelector('input');checkbox.checked=!!t.done;checkbox.setAttribute('aria-label',`${t.done?'Reabrir':'Concluir'} ${t.title}`);checkbox.onchange=()=>{t.done=checkbox.checked;t.completedAt=t.done?new Date().toISOString():null;save();render();notify(t.done?'Tarefa concluída. Um passo a mais!':'Tarefa reaberta.')};row.querySelector('.task-title').textContent=t.title;row.querySelector('.task-title').onclick=()=>openTask(t);row.querySelector('.deadline').textContent=formatDate(t.date);if(t.date&&t.date<today&&!t.done){row.querySelector('.deadline').textContent+=' · Atrasada';row.querySelector('.deadline').classList.add('late')}row.querySelector('.badge').textContent=t.priority==='high'?'Alta prioridade':'Normal';row.querySelector('.badge').classList.toggle('high',t.priority==='high');row.querySelector('.edit').onclick=()=>openTask(t);$('#tasks').append(row)}const focus=[...pending].sort((a,b)=>Number(b.priority==='high')-Number(a.priority==='high')||(a.date||'9999').localeCompare(b.date||'9999'))[0];$('#focus-text').textContent=focus?focus.title:'Adicione sua primeira tarefa e escolha por onde começar.';$('#focus-button').textContent=focus?'Ver tarefa ↗':'Escolher uma tarefa ↗';$('#focus-button').onclick=()=>openTask(focus)}
function openTask(task){editing=task?.id||null;const f=$('#task-form');f.reset();f.elements.title.value=task?.title||'';f.elements.notes.value=task?.notes||'';f.elements.date.value=task?.date??dateKey();f.elements.priority.value=task?.priority||'normal';$('#dialog-title').textContent=task?'Editar tarefa':'Nova tarefa';$('#delete').hidden=!task;$('#dialog').showModal();f.elements.title.focus()}
$('#add').onclick=()=>openTask();$('#close').onclick=$('#cancel').onclick=()=>$('#dialog').close();$('#task-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget,title=f.elements.title.value.trim();if(!title){f.elements.title.setCustomValidity('Escreva o nome da tarefa.');f.elements.title.reportValidity();return}const values={title,notes:f.elements.notes.value.trim(),date:f.elements.date.value,priority:f.elements.priority.value};if(editing)Object.assign(tasks.find(t=>t.id===editing),values);else tasks.push({...values,id:crypto.randomUUID(),done:false,createdAt:new Date().toISOString()});const saved=save();$('#dialog').close();render();if(saved)notify(editing?'Tarefa atualizada.':'Tarefa adicionada.')};$('#task-form').elements.title.oninput=e=>e.target.setCustomValidity('');$('#delete').onclick=()=>{const index=tasks.findIndex(t=>t.id===editing);if(index<0)return;undo={task:tasks[index],index};tasks.splice(index,1);save();$('#dialog').close();render();notify('Tarefa excluída.',true)};$('#toast button').onclick=()=>{if(!undo)return;tasks.splice(undo.index,0,undo.task);undo=null;save();render();notify('Tarefa restaurada.')};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelectorAll('[data-priority]').forEach(b=>b.onclick=()=>{priority=b.dataset.priority;document.querySelectorAll('[data-priority]').forEach(x=>x.classList.toggle('selected',x===b));render()});$('#search').oninput=$('#sort').onchange=render;$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),tasks},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='clareza-tarefas-'+dateKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Tarefas exportadas.')};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&!$('#dialog').open){e.preventDefault();openTask()}});window.addEventListener('storage',e=>{if(e.key===key){try{const data=JSON.parse(e.newValue||'[]');if(Array.isArray(data)){tasks=data;render()}}catch{notify('Não foi possível atualizar as tarefas desta aba.')}}});render();
